        private static Dictionary<ushort, RegTableItem> _byAddr;

        /// <summary>依位址查表 (第一次呼叫時建索引, 之後重用); 供 NamedMacroFormatter 產生 .h 時查 DependsOn/Descption 用</summary>
        public static bool TryGetByAddr(ushort addr, out RegTableItem item)
        {
            if (_byAddr == null)
            {
                _byAddr = new Dictionary<ushort, RegTableItem>();
                foreach (RegTableItem it in Items)
                    if (!_byAddr.ContainsKey(it.Addr))
                        _byAddr[it.Addr] = it;
            }
            return _byAddr.TryGetValue(addr, out item);
        }
